//! The tables generated by `xtask gen-completion` and their lookups.
//!
//! The core packages (`CompletionDb::builtin`'s) are static tables in `generated.rs`. Every
//! other package is a zstd frame of `packages.zst` (embedded with `include_bytes!`, indexed by
//! `PACKED`), decompressed the first time [`package`] asks for it and kept for the rest of the
//! process: the decompressed text is leaked once and the tables borrow from it, so a package
//! costs its tables' size, once, and only in processes that load it.

use crate::generated::{
    CLASS_NAMES, COMMON_COMMANDS, COMMON_ENVIRONMENTS, GLYPHS, PACKAGE_NAMES, PACKAGES, PACKED,
    PACKED_BYTES, TIKZ_LIBRARIES,
};
use crate::{CmdEntry, EnvEntry, Mode};
use lemma_syntax::ArgKind;
use std::io::Read as _;
use std::sync::Mutex;

/// A command of a package table.
#[derive(Debug)]
pub(crate) struct GenCmd {
    pub(crate) entry: CmdEntry,
    /// The argument placeholders for display (`{num}{den}`); empty without arguments.
    pub(crate) sig: &'static str,
    /// Marked unusual (`#*`) in the word list: ranked after the usual commands.
    pub(crate) unusual: bool,
    /// Of no particular mode (`Mode::Any`) but at home in text, not in formulas: ranked far
    /// down in math (`\frame`, `\footref`, `\figurename`; see xtask `text_leaning`).
    pub(crate) text_leaning: bool,
}

/// An environment of a package table.
#[derive(Debug)]
pub(crate) struct GenEnv {
    pub(crate) entry: EnvEntry,
    /// `MathOnly` for environments used inside math (`pmatrix`), `TextOnly` for those that start
    /// math (`align`).
    pub(crate) mode: Mode,
    pub(crate) unusual: bool,
    /// Like [`GenCmd::text_leaning`] (`itemize`, `figure`, `center`).
    pub(crate) text_leaning: bool,
}

/// One word list (`amsmath`, `class-amsart`, …).
#[derive(Debug)]
pub(crate) struct Package {
    pub(crate) name: &'static str,
    /// Packages this one loads (`#include:`), in order.
    pub(crate) includes: &'static [&'static str],
    /// Sorted by name.
    pub(crate) commands: &'static [GenCmd],
    /// Sorted by name.
    pub(crate) environments: &'static [GenEnv],
    /// Commands with a classified argument (reference, citation, label, file, package), sorted.
    pub(crate) args: &'static [(&'static str, ArgKind)],
}

/// A package of `packages.zst`: its zstd frame is `PACKED_BYTES[at..at + len]`.
#[derive(Debug)]
pub(crate) struct Packed {
    pub(crate) name: &'static str,
    pub(crate) at: u32,
    pub(crate) len: u32,
    /// Packages this one loads (`#include:`), in order.
    pub(crate) includes: &'static [&'static str],
}

/// The packages decompressed so far, in order.
static DECODED: Mutex<Vec<&'static Package>> = Mutex::new(Vec::new());

/// Builds a [`GenCmd`] (keeps the generated file short).
#[allow(clippy::too_many_arguments)]
pub(crate) const fn c(
    package: &'static str,
    name: &'static str,
    snippet: &'static str,
    mode: Mode,
    glyph: Option<char>,
    sig: &'static str,
    unusual: bool,
    text_leaning: bool,
) -> GenCmd {
    GenCmd {
        entry: CmdEntry {
            name,
            snippet,
            mode,
            package,
            glyph,
        },
        sig,
        unusual,
        text_leaning,
    }
}

/// Builds a [`GenEnv`].
#[allow(clippy::too_many_arguments)]
pub(crate) const fn e(
    package: &'static str,
    name: &'static str,
    body: &'static str,
    math: bool,
    mode: Mode,
    unusual: bool,
    text_leaning: bool,
) -> GenEnv {
    GenEnv {
        entry: EnvEntry {
            name,
            body,
            math,
            package,
        },
        mode,
        unusual,
        text_leaning,
    }
}

/// The package table called `name`: a static one, else the packed one (decompressed on first
/// use).
pub(crate) fn package(name: &str) -> Option<&'static Package> {
    if let Ok(i) = PACKAGES.binary_search_by(|p| p.name.cmp(name)) {
        return Some(PACKAGES[i]);
    }
    let packed = &PACKED[PACKED.binary_search_by(|p| p.name.cmp(name)).ok()?];
    let mut decoded = DECODED.lock().unwrap_or_else(|e| e.into_inner());
    if let Some(p) = decoded.iter().find(|p| p.name == packed.name) {
        return Some(p);
    }
    let start = packed.at as usize;
    let frame = PACKED_BYTES.get(start..start + packed.len as usize)?;
    let pkg: &'static Package = Box::leak(Box::new(decode(packed, frame)?));
    decoded.push(pkg);
    Some(pkg)
}

/// Every package that has a table, sorted by name.
pub(crate) fn packages() -> Vec<&'static str> {
    let mut names: Vec<&'static str> = PACKAGES
        .iter()
        .map(|p| p.name)
        .chain(PACKED.iter().map(|p| p.name))
        .collect();
    names.sort_unstable();
    names
}

/// Whether `name` is a static (core) table.
pub(crate) fn is_static(name: &str) -> bool {
    PACKAGES.binary_search_by(|p| p.name.cmp(name)).is_ok()
}

/// The packages decompressed so far in this process, in order.
pub(crate) fn decompressed() -> Vec<&'static str> {
    let decoded = DECODED.lock().unwrap_or_else(|e| e.into_inner());
    decoded.iter().map(|p| p.name).collect()
}

/// The size of the packed tables (`packages.zst`) in bytes.
pub(crate) fn packed_size() -> usize {
    PACKED_BYTES.len()
}

/// Decompresses and parses one packed package (the format of xtask's `encode`). The text is
/// leaked: the tables borrow their strings from it.
fn decode(packed: &Packed, frame: &[u8]) -> Option<Package> {
    let mut decoder = ruzstd::decoding::StreamingDecoder::new(frame).ok()?;
    let mut bytes = Vec::new();
    decoder.read_to_end(&mut bytes).ok()?;
    let text: &'static str = Box::leak(String::from_utf8(bytes).ok()?.into_boxed_str());
    let package = packed.name;
    let mut sections = text.split('\u{1d}');
    let (_includes, commands, environments, args) = (
        sections.next()?,
        sections.next()?,
        sections.next()?,
        sections.next()?,
    );
    let records = |section: &'static str| {
        section
            .split_terminator('\u{1e}')
            .map(|r| r.split('\u{1f}').collect::<Vec<&'static str>>())
    };
    let mode = |m: &str| match m {
        "M" => Some(Mode::MathOnly),
        "T" => Some(Mode::TextOnly),
        "A" => Some(Mode::Any),
        _ => None,
    };
    let mut cmds = Vec::new();
    for f in records(commands) {
        let [name, snippet, m, glyph, sig, flags] = f[..] else {
            return None;
        };
        let mut glyph_chars = glyph.chars();
        cmds.push(c(
            package,
            name,
            snippet,
            mode(m)?,
            glyph_chars.next(),
            sig,
            flags.contains('u'),
            flags.contains('t'),
        ));
    }
    let mut envs = Vec::new();
    for f in records(environments) {
        let [name, body, math, m, flags] = f[..] else {
            return None;
        };
        envs.push(e(
            package,
            name,
            body,
            math == "1",
            mode(m)?,
            flags.contains('u'),
            flags.contains('t'),
        ));
    }
    let mut arg_kinds = Vec::new();
    for f in records(args) {
        let [cmd, kind] = f[..] else {
            return None;
        };
        let kind = match kind {
            "R" => ArgKind::Ref,
            "C" => ArgKind::Cite,
            "L" => ArgKind::Label,
            "F" => ArgKind::File,
            "P" => ArgKind::Package,
            _ => return None,
        };
        arg_kinds.push((cmd, kind));
    }
    Some(Package {
        name: package,
        includes: packed.includes,
        commands: Box::leak(cmds.into_boxed_slice()),
        environments: Box::leak(envs.into_boxed_slice()),
        args: Box::leak(arg_kinds.into_boxed_slice()),
    })
}

/// Where a command or environment stands in `data/completion/common.txt`: the ranking bonus
/// (1 to 4) and the rank (0 = most used). Entries not in the list have bonus 0 and the rank
/// `u32::MAX`.
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub(crate) struct Common {
    pub(crate) bonus: i32,
    pub(crate) rank: u32,
}

/// The `common.txt` entry of command `name` (without the backslash).
pub(crate) fn common_command(name: &str) -> Common {
    lookup_common(COMMON_COMMANDS, name)
}

/// The `common.txt` entry of environment `name`.
pub(crate) fn common_environment(name: &str) -> Common {
    lookup_common(COMMON_ENVIRONMENTS, name)
}

fn lookup_common(table: &[(&str, i8, u16)], key: &str) -> Common {
    match table.binary_search_by(|(k, _, _)| (*k).cmp(key)) {
        Ok(i) => Common {
            bonus: i32::from(table[i].1),
            rank: u32::from(table[i].2),
        },
        Err(_) => Common {
            bonus: 0,
            rank: u32::MAX,
        },
    }
}

/// Names offered in `\usepackage`, `\documentclass` and `\usetikzlibrary` arguments.
pub(crate) fn package_names() -> &'static [&'static str] {
    PACKAGE_NAMES
}

pub(crate) fn class_names() -> &'static [&'static str] {
    CLASS_NAMES
}

pub(crate) fn tikz_libraries() -> &'static [&'static str] {
    TIKZ_LIBRARIES
}

/// How a package is named in completion details: `LaTeX` for the kernel lists, the user-facing
/// package for the parts amsmath, amssymb and tikz-cd load, the class name for `class-*`.
pub(crate) fn package_label(name: &str) -> &str {
    match name {
        "latex-document" | "latex-dev" => "LaTeX",
        "amstext" | "amsopn" | "amsbsy" => "amsmath",
        "amsfonts" => "amssymb",
        "tikzlibrarycd" => "tikz-cd",
        _ => name.strip_prefix("class-").unwrap_or(name),
    }
}

/// The Unicode glyph a piece of math code stands for: `\alpha` → α, `\mathbb{Z}` → ℤ,
/// `\mathcal{O}` → 𝒪, `\to` → →.
///
/// The code may be wrapped in braces or `\ensuremath{…}`, and a one-letter alphabet argument may
/// be written without braces (`\mathbb Z`). Anything else, including code with arguments
/// (`\operatorname{Hom}`), has no glyph.
pub fn glyph_for(code: &str) -> Option<char> {
    let mut s = code.trim();
    loop {
        if let Some(inner) = s.strip_prefix("\\ensuremath") {
            s = inner.trim_start();
        }
        match s.strip_prefix('{').and_then(|r| r.strip_suffix('}')) {
            Some(inner) if balanced(inner) => s = inner.trim(),
            _ => break,
        }
    }
    let key = normalize_alphabet(s);
    let key = key.as_deref().unwrap_or(s);
    GLYPHS
        .binary_search_by(|(k, _)| (*k).cmp(key))
        .ok()
        .map(|i| GLYPHS[i].1)
}

/// `\mathbb Z` and `\mathbb{ Z }` → `\mathbb{Z}`; `None` when `s` is not such a form.
fn normalize_alphabet(s: &str) -> Option<String> {
    let rest = s.strip_prefix('\\')?;
    let letters = rest.bytes().take_while(u8::is_ascii_alphabetic).count();
    if letters == 0 || letters == rest.len() {
        return None;
    }
    let (cmd, arg) = rest.split_at(letters);
    let arg = arg.trim();
    let arg = arg
        .strip_prefix('{')
        .and_then(|a| a.strip_suffix('}'))
        .map_or(arg, str::trim);
    let mut chars = arg.chars();
    match (chars.next(), chars.next()) {
        (Some(ch), None) if ch.is_ascii_alphanumeric() => Some(format!("\\{cmd}{{{ch}}}")),
        _ => None,
    }
}

/// Whether the braces of `s` balance (so `{a}{b}` is not taken for one group).
fn balanced(s: &str) -> bool {
    let mut depth = 0i32;
    for b in s.bytes() {
        match b {
            b'{' => depth += 1,
            b'}' => {
                depth -= 1;
                if depth < 0 {
                    return false;
                }
            }
            _ => {}
        }
    }
    depth == 0
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn tables_are_sorted_for_binary_search() {
        assert!(PACKAGES.windows(2).all(|w| w[0].name < w[1].name));
        assert!(PACKED.windows(2).all(|w| w[0].name < w[1].name));
        assert!(GLYPHS.windows(2).all(|w| w[0].0 < w[1].0));
        assert!(COMMON_COMMANDS.windows(2).all(|w| w[0].0 < w[1].0));
        assert!(COMMON_ENVIRONMENTS.windows(2).all(|w| w[0].0 < w[1].0));
        for name in packages() {
            let p = package(name).expect("every listed package decodes");
            assert!(
                p.commands
                    .windows(2)
                    .all(|w| w[0].entry.name < w[1].entry.name),
                "{}",
                p.name
            );
            assert!(
                p.environments
                    .windows(2)
                    .all(|w| w[0].entry.name < w[1].entry.name),
                "{}",
                p.name
            );
            assert!(p.args.windows(2).all(|w| w[0].0 < w[1].0), "{}", p.name);
        }
        for list in [PACKAGE_NAMES, CLASS_NAMES, TIKZ_LIBRARIES] {
            assert!(list.windows(2).all(|w| w[0] < w[1]));
        }
    }

    #[test]
    fn glyphs() {
        assert_eq!(glyph_for(r"\alpha"), Some('α'));
        assert_eq!(glyph_for(r"\mathbb{Z}"), Some('ℤ'));
        assert_eq!(glyph_for(r"\mathbb Z"), Some('ℤ'));
        assert_eq!(glyph_for(r"{\mathbb{ Z }}"), Some('ℤ'));
        assert_eq!(glyph_for(r"\ensuremath{\mathbb{N}}"), Some('ℕ'));
        assert_eq!(glyph_for(r"\mathcal{O}"), Some('𝒪'));
        assert_eq!(glyph_for(r"\varepsilon"), Some('ε'));
        assert_eq!(glyph_for(r"\epsilon"), Some('ϵ'));
        assert_eq!(glyph_for(r"\to"), Some('→'));
        assert_eq!(glyph_for(r"\operatorname{Hom}"), None);
        assert_eq!(glyph_for(r"\mathbb{ZZ}"), None);
        assert_eq!(glyph_for(r"{\alpha}{\beta}"), None);
        assert_eq!(glyph_for(r"\hat"), None);
        assert_eq!(glyph_for(""), None);
    }

    #[test]
    fn package_lookup_and_labels() {
        assert!(package("amsmath").is_some());
        assert!(package("no-such-package").is_none());
        // A packed package decodes once; asking again gives the same tables.
        let a = package("siunitx").expect("siunitx is packed");
        assert!(!is_static("siunitx") && is_static("amsmath"));
        assert!(std::ptr::eq(a, package("siunitx").unwrap()));
        assert_eq!(a.name, "siunitx");
        assert!(a.commands.iter().all(|c| c.entry.package == "siunitx"));
        let si = a.commands.iter().find(|c| c.entry.name == "SI").unwrap();
        assert_eq!(si.entry.mode, Mode::Any);
        assert!(decompressed().contains(&"siunitx"));
        assert_eq!(package_label("latex-dev"), "LaTeX");
        assert_eq!(package_label("amsopn"), "amsmath");
        assert_eq!(package_label("class-amsart"), "amsart");
        assert_eq!(package_label("hyperref"), "hyperref");
        assert_eq!(common_command("frac"), Common { bonus: 4, rank: 0 });
        assert_eq!(common_environment("align").bonus, 4);
        assert_eq!(
            common_command("frown"),
            Common {
                bonus: 0,
                rank: u32::MAX
            }
        );
        assert_eq!(common_command("align").bonus, 0);
        assert!(common_command("mathbb").rank < common_command("sum").rank);
    }
}
